-- PT118-S4-Q5. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT118-S4-Q5$batch03$ AND q.stimulus=$batch03$Rats fed high doses of the artificial sweetener saccharin develop silicate crystals that are toxic to cells lining the bladder. When the cells regenerate, some are cancerous and form tumors. Unlike rats, mice fed high doses of saccharin do not get bladder cancer.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, does the most to resolve the apparent discrepancy in the information above?$batch03$ AND q.correct_choice=$batch03$A$batch03$) THEN RAISE EXCEPTION 'Question changed: PT118-S4-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT118-S4-Q5$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S4-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT118-S4-Q5$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$In rats, high doses of saccharin create toxic silicate crystals, and regenerating cells can become cancerous.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Mice on the same high doses do not get bladder cancer?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The rat chain starts with crystals. If mice never form the crystals, the chain never starts. Look for a difference between the species at that first step.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a difference that stops mice from forming the crystals.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT118-S4-Q5$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$The urine proteins that react with saccharin to form crystals exist in rats but not mice. No crystals, no damage, no cancer.$batch03$), ($batch03$B$batch03$, $batch03$Faster regeneration in mice could mean more chances for cancerous cells, not fewer. It does not explain the difference.$batch03$), ($batch03$C$batch03$, $batch03$Both rats and mice got high doses, so dose cannot separate them.$batch03$), ($batch03$D$batch03$, $batch03$Where the crystals are toxic would apply to both species if both formed them.$batch03$), ($batch03$E$batch03$, $batch03$Other sweeteners are not the issue. This also runs the wrong way, giving mice crystals and rats none.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT118-S4-Q5$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
